from numeric_series import *
from typed_sequences import *
from checked_integer import *
from ail import read_bytes, write_stdout_bytes
import sys

def integer_series_native_between(series: IntegerSeries, low: int, high: int) -> IntegerSeries:
    values: list[int] = series.values
    for i in range(1, len(values)):
        if values[i - 1] > values[i]:
            raise ValueError
    selected: list[int] = native_between(values, low, high)
    return integer_series_new(selected)

def float_series_native_average(series: FloatSeries, window: int) -> FloatSeries:
    values: list[float] = series.values
    if window <= 0 or window > len(values):
        raise ValueError
    averages: list[float] = native_moving_average(values, window)
    result: FloatSeries = float_series_new(averages)
    native_release_smoothing()
    return result

def main() -> int:
    if len(sys.argv) != 5:
        print('usage: numeric_series_native INPUT COLUMN LOW HIGH', file=sys.stderr)
        return 2
    try:
        column: int = parse_int64_decimal(sys.argv[2])
        low: int = parse_int64_decimal(sys.argv[3])
        high: int = parse_int64_decimal(sys.argv[4])
        if column < 0:
            raise ValueError
        text: str = read_bytes(sys.argv[1]).decode('utf-8')
        values: list[int] = integer_column_values(text, column)
        series: IntegerSeries = integer_series_new(values)
        selected: IntegerSeries = integer_series_native_between(series, low, high)
        rendered: str = integer_series_render(selected)
        write_stdout_bytes(rendered.encode('utf-8'))
        return 0
    except ValueError:
        print('invalid integer column, range, or ascending data', file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print('input must be UTF-8', file=sys.stderr)
        return 2
    except OSError:
        print('numeric series input or output failed', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
